import hashlib, hmac, uuid

secret = "mysecret"
challenge_str = "12345678-1234-1234-1234-123456789abc"
u = uuid.UUID(challenge_str)
target = "5508630c49ef4db5fb30098a848232bc05a6464cc40ef6a801eb99b75d8f7242"

def test_pair(k, m, desc):
    for algo in [hashlib.sha256, hashlib.sha512, hashlib.sha1]:
        try:
            res = hmac.new(k, m, algo).hexdigest()
            if res == target:
                print("FOUND HMAC MATCH:", desc, algo.__name__)
        except Exception:
            pass

def test_hash(data, desc):
    for algo in [hashlib.sha256, hashlib.sha512, hashlib.sha1, hashlib.blake2b, hashlib.blake2s]:
        try:
            res = algo(data).hexdigest()
            if res == target:
                print("FOUND HASH MATCH:", desc, algo.__name__)
        except Exception:
            pass

keys = [
    secret.encode(),
    hashlib.sha256(secret.encode()).digest(),
    hashlib.sha256(secret.encode()).hexdigest().encode(),
    challenge_str.encode(),
    u.bytes,
    u.hex.encode(),
]

msgs = [
    secret.encode(),
    hashlib.sha256(secret.encode()).digest(),
    hashlib.sha256(secret.encode()).hexdigest().encode(),
    challenge_str.encode(),
    u.bytes,
    u.hex.encode(),
    (secret + challenge_str).encode(),
    (challenge_str + secret).encode(),
    f"{secret}:{challenge_str}".encode(),
    f"{challenge_str}:{secret}".encode(),
]

for ik, k in enumerate(keys):
    for im, m in enumerate(msgs):
        test_pair(k, m, f"k[{ik}] m[{im}]")

for im, m in enumerate(msgs):
    test_hash(m, f"m[{im}]")
'"}

