use sha2::{Digest, Sha256};
use uuid::Uuid;

fn compute_auth(secret: &str, challenge: &Uuid) -> String {
    let key_hash = Sha256::digest(secret.as_bytes());
    let mut k_ipad = [0x36u8; 64];
    let mut k_opad = [0x5cu8; 64];

    for i in 0..32 {
        k_ipad[i] ^= key_hash[i];
        k_opad[i] ^= key_hash[i];
    }

    let mut inner = Sha256::new();
    inner.update(&k_ipad);
    inner.update(challenge.as_bytes());
    let inner_hash = inner.finalize();

    let mut outer = Sha256::new();
    outer.update(&k_opad);
    outer.update(&inner_hash);
    let outer_hash = outer.finalize();

    hex::encode(outer_hash)
}

fn main() {
    let secret = "mysecret";
    let u = Uuid::parse_str("12345678-1234-1234-1234-123456789abc").unwrap();
    let res = compute_auth(secret, &u);
    println!("Res: {}", res);
    assert_eq!(res, "5508630c49ef4db5fb30098a848232bc05a6464cc40ef6a801eb99b75d8f7242");
    println!("MATCH!");
}
EOF

