cat <<'EOF' > src/client.rs
use crate::args::LocalOptions;
use crate::shared::{
    compute_auth, log_info, log_warn, recv_msg, send_msg, ClientMessage, ServerMessage, CONTROL_PORT,
};
use anyhow::{anyhow, Context, Result};
use std::io::{copy, Read, Write};
use std::net::TcpStream;
use std::sync::Arc;
use std::thread;
use std::time::Duration;
use uuid::Uuid;

const CLIENT_TARGET: &str = "bore_cli::client";

pub fn run(opts: LocalOptions) -> Result<()> {
    let opts = Arc::new(opts);
    let server_addr = format!("{}:{}", opts.to, CONTROL_PORT);
    let mut control_stream = TcpStream::connect(&server_addr)
        .with_context(|| format!("could not connect to {server_addr}"))?;

    control_stream.set_read_timeout(Some(Duration::from_secs(3)))?;

    if let Some(secret) = &opts.secret {
        let msg: ServerMessage = match recv_msg(&mut control_stream) {
            Ok(m) => m,
            Err(e) => {
                let err_str = e.to_string();
                if err_str.contains("timed out") || err_str.contains("WouldBlock") {
                    return Err(anyhow!("timed out waiting for initial message")
                        .context(anyhow::Error::msg("deadline has elapsed")));
                }
                return Err(e);
            }
        };

        match msg {
            ServerMessage::Challenge(challenge) => {
                let auth_hex = compute_auth(secret, &challenge);
                send_msg(&mut control_stream, &ClientMessage::Authenticate(auth_hex))?;
            }
            ServerMessage::Hello(_) => {
                return Err(anyhow!("expected authentication challenge, but no secret was required"));
            }
            ServerMessage::Error(e) => {
                return Err(anyhow!("server error: {e}"));
            }
            _ => {
                return Err(anyhow!("unexpected initial message from server"));
            }
        }
    }

    send_msg(&mut control_stream, &ClientMessage::Hello(opts.port))?;

    let hello_resp: ServerMessage = recv_msg(&mut control_stream)?;
    let remote_port = match hello_resp {
        ServerMessage::Hello(port) => port,
        ServerMessage::Error(e) => {
            return Err(anyhow!("server error: {e}"));
        }
        _ => {
            return Err(anyhow!("unexpected initial non-hello message"));
        }
    };

    log_info(CLIENT_TARGET, None, &format!("connected to server remote_port={remote_port}"));
    log_info(CLIENT_TARGET, None, &format!("listening at {}:{remote_port}", opts.to));

    control_stream.set_read_timeout(None)?;

    loop {
        let msg: ServerMessage = match recv_msg(&mut control_stream) {
            Ok(m) => m,
            Err(_) => break,
        };

        match msg {
            ServerMessage::Heartbeat => {}
            ServerMessage::Connection(id) => {
                let opts = Arc::clone(&opts);
                thread::spawn(move || {
                    if let Err(e) = handle_proxy(opts, id) {
                        log_warn(
                            CLIENT_TARGET,
                            Some(("proxy", "id", id.to_string())),
                            &format!("connection exited with error err={e:#}"),
                        );
                    } else {
                        log_info(CLIENT_TARGET, Some(("proxy", "id", id.to_string())), "connection exited");
                    }
                });
            }
            _ => {}
        }
    }

    Ok(())
}

fn handle_proxy(opts: Arc<LocalOptions>, id: Uuid) -> Result<()> {
    log_info(CLIENT_TARGET, Some(("proxy", "id", id.to_string())), "new connection");

    let local_addr = format!("{}:{}", opts.local_host, opts.local_port);
    let mut local_stream = TcpStream::connect(&local_addr)
        .with_context(|| format!("could not connect to {local_addr}"))?;

    let server_addr = format!("{}:{}", opts.to, CONTROL_PORT);
    let mut server_stream = TcpStream::connect(&server_addr)
        .with_context(|| format!("could not connect to {server_addr}"))?;

    if let Some(secret) = &opts.secret {
        server_stream.set_read_timeout(Some(Duration::from_secs(3)))?;
        let msg: ServerMessage = recv_msg(&mut server_stream)?;
        server_stream.set_read_timeout(None)?;
        if let ServerMessage::Challenge(challenge) = msg {
            let auth_hex = compute_auth(secret, &challenge);
            send_msg(&mut server_stream, &ClientMessage::Authenticate(auth_hex))?;
        }
    }

    send_msg(&mut server_stream, &ClientMessage::Accept(id))?;

    let mut local_read = local_stream.try_clone()?;
    let mut local_write = local_stream;
    let mut server_read = server_stream.try_clone()?;
    let mut server_write = server_stream;

    let t1 = thread::spawn(move || copy(&mut local_read, &mut server_write));
    let t2 = thread::spawn(move || copy(&mut server_read, &mut local_write));

    let _ = t1.join();
    let _ = t2.join();

    Ok(())
}
EOF

cat <<'EOF' > src/server.rs
use crate::args::ServerOptions;
use crate::shared::{
    compute_auth, log_info, log_warn, recv_msg, send_msg, ClientMessage, ServerMessage, CONTROL_PORT,
};
use anyhow::Result;
use rand::Rng;
use std::collections::HashMap;
use std::io::copy;
use std::net::{TcpListener, TcpStream};
use std::sync::mpsc::{channel, Sender};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::Duration;
use uuid::Uuid;

const SERVER_TARGET: &str = "bore_cli::server";

type PendingMap = Arc<Mutex<HashMap<Uuid, Sender<TcpStream>>>>;

pub fn run(opts: ServerOptions) -> Result<()> {
    let opts = Arc::new(opts);
    let pending_conns: PendingMap = Arc::new(Mutex::new(HashMap::new()));

    let bind_addr = format!("{}:{}", opts.bind_addr, CONTROL_PORT);
    let listener = TcpListener::bind(&bind_addr)?;

    log_info(SERVER_TARGET, None, &format!("server listening addr={}", opts.bind_addr));

    for stream in listener.incoming() {
        let stream = match stream {
            Ok(s) => s,
            Err(_) => continue,
        };

        let opts = Arc::clone(&opts);
        let pending = Arc::clone(&pending_conns);

        thread::spawn(move || {
            let _ = handle_connection(stream, opts, pending);
        });
    }

    Ok(())
}

fn handle_connection(
    mut stream: TcpStream,
    opts: Arc<ServerOptions>,
    pending_conns: PendingMap,
) -> Result<()> {
    let peer_addr = stream.peer_addr().map(|a| a.to_string()).unwrap_or_default();
    let span = ("control", "addr", peer_addr);

    log_info(SERVER_TARGET, Some(span.clone()), "incoming connection");

    stream.set_read_timeout(Some(Duration::from_secs(3)))?;

    if let Some(secret) = &opts.secret {
        let challenge = Uuid::new_v4();
        send_msg(&mut stream, &ServerMessage::Challenge(challenge))?;

        let msg: ClientMessage = match recv_msg(&mut stream) {
            Ok(m) => m,
            Err(e) => {
                let err_msg = e.to_string();
                if err_msg.contains("timed out") || err_msg.contains("WouldBlock") {
                    log_warn(SERVER_TARGET, Some(span.clone()), "connection exited with error err=timed out waiting for initial message");
                } else {
                    log_warn(SERVER_TARGET, Some(span.clone()), &format!("server handshake failed err={e:#}"));
                }
                log_info(SERVER_TARGET, Some(span.clone()), "connection exited");
                return Ok(());
            }
        };

        match msg {
            ClientMessage::Authenticate(auth_hex) => {
                let expected = compute_auth(secret, &challenge);
                if auth_hex != expected {
                    send_msg(&mut stream, &ServerMessage::Error("invalid secret".to_string()))?;
                    log_warn(SERVER_TARGET, Some(span.clone()), "server handshake failed err=invalid secret");
                    log_info(SERVER_TARGET, Some(span.clone()), "connection exited");
                    return Ok(());
                }
            }
            _ => {
                send_msg(
                    &mut stream,
                    &ServerMessage::Error("server requires secret, but no secret was provided".to_string()),
                )?;
                log_warn(
                    SERVER_TARGET,
                    Some(span.clone()),
                    "server handshake failed err=server requires secret, but no secret was provided",
                );
                log_info(SERVER_TARGET, Some(span.clone()), "connection exited");
                return Ok(());
            }
        }
    }

    let msg: ClientMessage = match recv_msg(&mut stream) {
        Ok(m) => m,
        Err(e) => {
            if opts.secret.is_none() {
                let err_msg = e.to_string();
                if err_msg.contains("timed out") || err_msg.contains("WouldBlock") {
                    log_warn(SERVER_TARGET, Some(span.clone()), "connection exited with error err=timed out waiting for initial message");
                } else {
                    log_warn(SERVER_TARGET, Some(span.clone()), &format!("connection exited with error err={e:#}"));
                }
            }
            log_info(SERVER_TARGET, Some(span.clone()), "connection exited");
            return Ok(());
        }
    };

    match msg {
        ClientMessage::Authenticate(_) => {
            log_warn(SERVER_TARGET, Some(span.clone()), "unexpected authenticate");
            log_info(SERVER_TARGET, Some(span.clone()), "connection exited");
            Ok(())
        }
        ClientMessage::Hello(requested_port) => {
            let bind_tunnels_ip = opts.bind_tunnels.as_deref().unwrap_or(&opts.bind_addr);

            let (tunnel_listener, assigned_port) = match bind_tunnel_listener(
                bind_tunnels_ip,
                requested_port,
                opts.min_port,
                opts.max_port,
            ) {
                Ok(res) => res,
                Err(err_str) => {
                    send_msg(&mut stream, &ServerMessage::Error(err_str))?;
                    log_info(SERVER_TARGET, Some(span.clone()), "connection exited");
                    return Ok(());
                }
            };

            send_msg(&mut stream, &ServerMessage::Hello(assigned_port))?;
            log_info(
                SERVER_TARGET,
                Some(span.clone()),
                &format!("new client host={bind_tunnels_ip} port={assigned_port}"),
            );

            let control_stream = Arc::new(Mutex::new(stream));
            let pending_conns_clone = Arc::clone(&pending_conns);
            let span_clone = span.clone();

            thread::spawn(move || {
                for incoming in tunnel_listener.incoming() {
                    let user_stream = match incoming {
                        Ok(s) => s,
                        Err(_) => break,
                    };

                    let user_addr = user_stream.peer_addr().map(|a| a.to_string()).unwrap_or_default();
                    log_info(
                        SERVER_TARGET,
                        Some(span_clone.clone()),
                        &format!("new connection addr={user_addr} port={assigned_port}"),
                    );

                    let conn_id = Uuid::new_v4();
                    let (tx, rx) = channel::<TcpStream>();

                    {
