    } else {
        let mut rng = rand::thread_rng();
        for _ in 0..100 {
            let port = rng.gen_range(min_port..=max_port);
            let addr = format!("{host}:{port}");
            if let Ok(l) = TcpListener::bind(&addr) {
                return Ok((l, port));
            }
        }
        Err("no available ports".to_string())
    }
}

fn bridge_sockets(mut s1: TcpStream, mut s2: TcpStream) {
    let mut r1 = match s1.try_clone() {
        Ok(r) => r,
        Err(_) => return,
    };
    let mut w1 = s1;
    let mut r2 = match s2.try_clone() {
        Ok(r) => r,
        Err(_) => return,
    };
    let mut w2 = s2;

    let t1 = thread::spawn(move || copy(&mut r1, &mut w2));
    let t2 = thread::spawn(move || copy(&mut r2, &mut w1));

