                    let (tx, rx) = channel::<TcpStream>();

                    {
                        let mut map = pending_conns_clone.lock().unwrap();
                        map.insert(conn_id, tx);
                    }

                    {
                        let mut ctrl = control_stream.lock().unwrap();
                        if let Err(e) = send_msg(&mut *ctrl, &ServerMessage::Connection(conn_id)) {
