                        }
                    }

                    let pending_conns_stale = Arc::clone(&pending_conns_clone);
                    thread::spawn(move || {
                        match rx.recv_timeout(Duration::from_secs(10)) {
                            Ok(data_stream) => {
                                bridge_sockets(user_stream, data_stream);
                            }
                            Err(_) => {
                                {
                                    let mut map = pending_conns_stale.lock().unwrap();
                                    map.remove(&conn_id);
                                }
                                log_warn(SERVER_TARGET, None, &format!("removed stale connection id={conn_id}"));
