            return Err("client port number not in allowed range".to_string());
        }
        let addr = format!("{host}:{requested_port}");
        match TcpListener::bind(&addr) {
            Ok(l) => Ok((l, requested_port)),
            Err(_) => Err("port already in use".to_string()),
        }
    } else {
        let mut rng = rand::thread_rng();
        for _ in 0..100 {
            let port = rng.gen_range(min_port..=max_port);
            let addr = format!("{host}:{port}");
            if let Ok(l) = TcpListener::bind(&addr) {
                return Ok((l, port));
            }
        }
        Err("no available ports".to_string())
    }
}

fn bridge_sockets(s1: TcpStream, s2: TcpStream) {
    let mut r1 = match s1.try_clone() {
        Ok(r) => r,
        Err(_) => return,
    };
    let mut w1 = s1;
    let mut r2 = match s2.try_clone() {
        Ok(r) => r,
        Err(_) => return,
    };
    let mut w2 = s2;

    let t1 = thread::spawn(move || copy(&mut r1, &mut w2));
    let t2 = thread::spawn(move || copy(&mut r2, &mut w1));

    let _ = t1.join();
    let _ = t2.join();
}
